#!/usr/bin/env python3
"""Render deploy/overlays/scenarios.yaml into one Kustomize overlay per deployment scenario (site).

Usage: python deploy/overlays/render.py [--check]
--check exits non-zero if the generated files are out of date (verify workflow).

Each overlay lists the scenario's Argo CD Applications (deploy/argocd/apps, generated from catalog.yaml), patches
them (extra Helm value files, replaced source paths), and, for the hybrid scenario, adds the Services that cross
between the two clusters as Cilium ClusterMesh global services:
  providing site: <name>-x, a ClusterIP Service with the original selector, global and shared;
  using site:     <name>-x without selector (global, not shared: endpoints come from the other cluster) and an
                  ExternalName <name> -> <name>-x, so workloads keep the DNS names they already use.
Cilium 1.17 has no MCS-API (ServiceExport), and global services can't be headless; this pattern needs neither and
leaves the original manifests untouched.
"""
import pathlib
import sys

import yaml

ROOT = pathlib.Path(__file__).resolve().parents[2]
OUT = ROOT / "deploy/overlays"
APPS = ROOT / "deploy/argocd/apps"
HEADER = "# generated by deploy/overlays/render.py from scenarios.yaml: do not edit\n"


def dump(obj):
    return yaml.safe_dump(obj, sort_keys=False, default_flow_style=False, width=120)


def crossing(entries, providing):
    docs = []
    for e in entries:
        x = e["name"] + "-x"
        ports = [{"name": p["name"], "port": p["port"]} for p in e["ports"]]
        ann = {"service.cilium.io/global": "true", "service.cilium.io/shared": "true" if providing else "false"}
        svc = {"apiVersion": "v1", "kind": "Service", "metadata": {"name": x, "namespace": e["ns"], "annotations": ann,
                                                                   "labels": {"difme/crossing": "true"}},
               "spec": {"ports": ports}}
        if providing:
            svc["spec"]["selector"] = e["selector"]
        docs.append(svc)
        if not providing:
            docs.append({"apiVersion": "v1", "kind": "Service",
                         "metadata": {"name": e["name"], "namespace": e["ns"], "labels": {"difme/crossing": "true"}},
                         "spec": {"type": "ExternalName", "externalName": f"{x}.{e['ns']}.svc.cluster.local", "ports": ports}})
    return docs


def render():
    catalog = yaml.safe_load((ROOT / "deploy/argocd/catalog.yaml").read_text())["components"]
    byname = {c["name"]: c for c in catalog}
    spec = yaml.safe_load((OUT / "scenarios.yaml").read_text())["scenarios"]
    files = {}
    for name, s in spec.items():
        d = OUT / name
        up = "/".join([".."] * (len(pathlib.Path(name).parts) + 2))  # from the overlay dir to the repo root
        profiles = s.get("profiles", [])
        chosen = [c["name"] for c in catalog if profiles == "all" or c["profile"] in profiles]
        chosen += [n for n in s.get("include", []) if n not in chosen]
        chosen = [n for n in chosen if n not in s.get("exclude", [])]
        for n in chosen:
            if n not in byname or not (APPS / f"{n}.yaml").exists():
                sys.exit(f"{name}: unknown component {n}")
        k = {"apiVersion": "kustomize.config.k8s.io/v1beta1", "kind": "Kustomization",
             "commonAnnotations": {"difme.dev/scenario": name},
             "resources": [f"{up}/deploy/argocd/apps/{n}.yaml" for n in chosen]}
        patches = []
        for comp, vals in (s.get("values") or {}).items():
            if comp not in chosen:
                continue
            if byname[comp]["kind"] != "helm":
                sys.exit(f"{name}: values for non-Helm component {comp}")
            ops = [{"op": "add", "path": "/spec/sources/0/helm/valueFiles/-", "value": f"$values/deploy/overlays/values/{v}"}
                   for v in vals]
            for v in vals:
                if not (OUT / "values" / v).exists():
                    sys.exit(f"{name}: missing values/{v}")
            patches.append({"target": {"group": "argoproj.io", "kind": "Application", "name": comp}, "patch": dump(ops)})
        for comp, path in (s.get("paths") or {}).items():
            if comp not in chosen:
                continue
            if byname[comp]["kind"] != "path" or not (ROOT / path).exists():
                sys.exit(f"{name}: bad path override {comp} -> {path}")
            patches.append({"target": {"group": "argoproj.io", "kind": "Application", "name": comp},
                            "patch": dump([{"op": "replace", "path": "/spec/source/path", "value": path}])})
        if patches:
            k["patches"] = patches
        docs = crossing(s.get("export", []), True) + crossing(s.get("import", []), False)
        if docs:
            k["resources"].append("crossing.yaml")
            files[d / "crossing.yaml"] = HEADER + "".join("---\n" + dump(x) for x in docs)
        files[d / "kustomization.yaml"] = HEADER + f"# {s['description']}\n" + dump(k)
    return files


def main():
    files = render()
    stale = [p for p, txt in files.items() if not p.exists() or p.read_text() != txt]
    if "--check" in sys.argv:
        if stale:
            sys.exit("out of date (run python deploy/overlays/render.py): " + ", ".join(str(p.relative_to(ROOT)) for p in stale))
        print("overlays current")
        return
    for p in stale:
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(files[p])
    print(f"{len(files)} files, {len(stale)} written")


if __name__ == "__main__":
    main()
